// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "initial funding failed");

        address recipient = address(0x123);
        vm.deal(recipient, 0);

        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        uint256 valueToSend = 0.5 ether;
        c.sendMoney(recipient, valueToSend);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        assertEq(contractBalanceAfter, contractBalanceBefore - valueToSend);
        assertEq(recipientBalanceAfter, recipientBalanceBefore + valueToSend);
    }
}
